style.css:
@-moz-document domain("youtube.com") {
/* --- 1. TU LOGO PERSONALIZADO --- */
    
    /* Ocultamos el logo original de YouTube */
    ytd-topbar-logo-renderer #logo-icon svg {
        display: none !important;
    }

    /* Inyectamos tu imagen Untitled231_20260429232840.png */
    ytd-topbar-logo-renderer #logo-icon::before {
        content: url("https://i.ibb.co/mFm8pP9v/Untitled231-20260429232840.png") !important;
        display: block !important;
        width: 140px !important; 
        height: 50px !important; 
        object-fit: contain !important;
        transform: translateY(-8px) !important;
    }

    /* Espaciado del contenedor del logo */
    ytd-topbar-logo-renderer {
        width: 150px !important;
    }

    /* --- 2. PALETA DE COLORES AESTHETIC --- */

    /* FONDO: Amarillo claro */
    body, ytd-app, #page-manager {
        background-color: #fff9ed !important; 
    }

    /* BARRA SUPERIOR: Rosa vibrante (hace juego con tu logo) */
    ytd-masthead {
        background-color: #ff85b3 !important; 
    }

    /* TEXTOS Y TÍTULOS: Naranja vibrante para visibilidad */
    #video-title, #content-text, .title.ytd-guide-entry-renderer, #channel-name, span.yt-formatted-string {
        color: #ff7800 !important;
        font-weight: bold !important;
    }

    /* BOTONES DE LIKE/DISLIKE Y MINIATURAS: Naranja saturado */
    ytd-segmented-like-dislike-button-renderer yt-icon,
    .yt-spec-button-shape-next--flat.yt-spec-button-shape-next--mono,
    #thumbnail.ytd-thumbnail {
        color: #ff7800 !important;
        fill: #ff7800 !important;
        border: 3px solid #ff7800 !important;
        border-radius: 12px !important;
    }

    /* BOTÓN SUSCRIBIRSE: Verde Lima (para combinar con el logo) */
    ytd-subscribe-button-renderer paper-button, 
    .yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono {
        background-color: #70D943 !important;
        color: #000000 !important;
        font-weight: bold !important;
    }

    /* BARRA DE BÚSQUEDA: Naranja con fondo blanco */
    ytd-searchbox #container.ytd-searchbox {
        border: 3px solid #ff7800 !important;
        background-color: #ffffff !important;
    }
    
    ytd-searchbox #search-icon-legacy.ytd-searchbox {
        background-color: #ff7800 !important;
    }

    /* BARRA DE PROGRESO DEL VIDEO: Naranja */
    .ytp-play-progress {
        background-color: #ff7800 !important;
    }
}
